const ENTRIES = Object.entries(LEXICON).flatMap(([id, levels]) =>
  Object.entries(levels).flatMap(([weight, words]) => words.split(/\s+/).filter(Boolean).map(word => ({
    id, weight: Number(weight), exact: word.startsWith('='), stem: word.replace(/^=/, ''),
  }))));

// Если подходит один предмет, второй и фоновый берём из пары, которая выглядит естественно.
const COMPANIONS = {
  book: ['pen', 'lamp'], phone: ['puzzles', 'headphones'], puzzles: ['lamp', 'pen'],
  coin: ['wallet', 'folder'], headphones: ['phone', 'book'], lamp: ['book', 'pen'],
  flowers: ['pen', 'book'], wallet: ['coin', 'folder'], folder: ['pen', 'coin'], pen: ['book', 'folder'],
};

export function words(text) {
  return (text.toLowerCase().replaceAll('ё', 'е').match(/[а-яa-z0-9]+/giu) || []);
}

// Баллы каждого объекта и слова заголовка, которые их дали.
export function scoreMeaning(text) {
  const result = new Map();
  for (const word of words(text)) {
    const best = new Map();
    for (const entry of ENTRIES) {
      const matched = entry.exact ? word === entry.stem : word.length >= 3 && word.startsWith(entry.stem);
      if (matched && entry.weight > (best.get(entry.id) || 0)) best.set(entry.id, entry.weight);
    }
    for (const [id, weight] of best) {
      const item = result.get(id) || { id, score: 0, words: [] };
      item.score += weight;
      item.words.push(word);
      result.set(id, item);
    }
  }
  return [...result.values()].sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
}

// Две главные позиции и одна фоновая. Пустой список, если в заголовке нет знакомых смыслов.
export function suggest(text, catalog) {
  const known = new Set(catalog.map(asset => asset.id));
  const ranked = scoreMeaning(text).filter(item => known.has(item.id));
  if (!ranked.length) return [];
  const chosen = [];
  const add = (id, role, reason) => {
    if (known.has(id) && !chosen.some(item => item.id === id)) chosen.push({ id, role, reason });
  };
  const reason = item => `по словам: ${[...new Set(item.words)].join(', ')}`;
  add(ranked[0].id, 'main', reason(ranked[0]));
  if (ranked[1]) add(ranked[1].id, 'main', reason(ranked[1]));
  for (const id of COMPANIONS[ranked[0].id]) if (chosen.length < 2) add(id, 'main', 'пара к главному объекту');
  if (ranked[2]) add(ranked[2].id, 'background', reason(ranked[2]));
  for (const id of [...COMPANIONS[chosen[1].id], ...COMPANIONS[ranked[0].id]]) {
    if (chosen.length < 3) add(id, 'background', 'фон для главных объектов');
  }
  return chosen;
}
